using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Evaluator;using Observatory.Framework.Files.Journal;using EDJP.Observatory;
class Program{static void Main(){var cases=new List<object>();foreach(ulong current in new ulong[]{42,99,777}){var settings=new StubSettings{MinimumBodyValue=0};Evaluator.Evaluator.EvalSettings=settings;var systems=new List<EDSystem>();foreach(var id in new ulong[]{42,99,42}){var sys=new EDSystem("Source"+systems.Count,id,DateTime.UnixEpoch,new Logger());foreach(var bodyid in new[]{9,1,5}){var scan=new Scan{BodyName="Source "+bodyid,PlanetClass="Earthlike body",MassEM=1,BodyID=bodyid};var body=new Body(scan,true,new BodyExtra()){BodyID=bodyid};body.UpdateValues();sys.Bodies.Add(bodyid,body);}systems.Add(sys);}var e=new Evaluator.Evaluator{settings=settings,current=new EDSystem("Current",current,DateTime.UnixEpoch,new Logger()),systems=systems,UIFilter=UIFilter.All};e.UpdateUI();cases.Add(new{current,headers=e.uiHandler.Headers,rows=e.uiHandler.Rows.Select(r=>r.BodyID).ToArray()});}Console.Write(JsonSerializer.Serialize(cases));}}
